<script setup lang="ts">
import { useForm, usePage } from '@inertiajs/vue3'; import { Plus, Trash2 } from 'lucide-vue-next'; import { computed, watch } from 'vue'; import { useI18n } from 'vue-i18n'; import Button from '@/Core/Components/Button.vue'; import Input from '@/Core/Components/Input.vue'; import Modal from '@/Core/Components/Modal.vue'; import Select from '@/Core/Components/Select.vue'; import Textarea from '@/Core/Components/Textarea.vue'; import { route } from '@/Core/lib/route'; import { omitTieredPriceOverrides } from './quotePricing'; import type { CatalogItemType, Quote, QuoteFormOptions, QuoteKind } from './types';
const props = withDefaults(defineProps<{ quote?: Quote | null; options: QuoteFormOptions }>(), { quote: null }); const open = defineModel<boolean>('open', { default: false }); const { t } = useI18n(); const page = usePage();
const line = () => ({ product_id: '', item_type: 'service' as CatalogItemType, name: '', unit: 'unit', description: '', quantity_milli: 1000, unit_price_amount: 0, discount_amount: 0, tax_bps: 0 });
const form = useForm({ deal_id: '', contact_id: '', company_id: '', price_list_id: '', kind: 'quotation' as QuoteKind, title: '', currency: page.props.app.currency, probability_percent: 50, valid_until: '', terms: '', notes: '', lines: [line()] });
const optionList = (items: Array<{ id: string; name: string }>) => [{ value: '', label: t('crm.common.notSet') }, ...items.map((item) => ({ value: item.id, label: item.name }))]; const kinds = computed(() => (['quotation', 'proposal'] as QuoteKind[]).map((value) => ({ value, label: t(`crm.quoteKinds.${value}`) })));
watch(open, (shown) => { if (!shown) return; const quote = props.quote; form.clearErrors(); form.deal_id = quote?.deal?.id ?? ''; form.contact_id = quote?.contact?.id ?? ''; form.company_id = quote?.company?.id ?? ''; form.price_list_id = quote?.priceListId ?? ''; form.kind = quote?.kind ?? 'quotation'; form.title = quote?.title ?? ''; form.currency = quote?.currency ?? page.props.app.currency; form.probability_percent = quote?.probabilityPercent ?? 50; form.valid_until = quote?.validUntil ?? ''; form.terms = quote?.terms ?? ''; form.notes = quote?.notes ?? ''; form.lines = quote?.lines.map((item) => ({ product_id: item.productId ?? '', item_type: item.itemType, name: item.name, unit: item.unit, description: item.description ?? '', quantity_milli: item.quantityMilli, unit_price_amount: item.unitPriceAmount, discount_amount: item.discountAmount, tax_bps: item.taxBps })) ?? [line()]; });
watch(() => form.deal_id, (id) => {
    const deal = props.options.deals.find((item) => item.id === id);
    if (!deal) return;
    form.contact_id = deal.contactId ?? '';
    form.company_id = deal.companyId ?? '';
    form.currency = deal.currency;
});
watch(() => form.price_list_id, (id) => {
    const priceList = props.options.priceLists.find((item) => item.id === id);
    if (priceList) form.currency = priceList.currency;
});
function selectProduct(index: number): void { const row = form.lines[index]; const product = props.options.products.find((item) => item.id === row?.product_id); if (!row || !product) return; row.item_type = product.type; row.name = product.name; row.unit = product.unit; row.description = product.description ?? ''; row.unit_price_amount = product.unitPriceAmount; row.tax_bps = product.taxBps; form.currency = props.options.priceLists.find((item) => item.id === form.price_list_id)?.currency ?? product.currency; }
function submit(): void {
    form.transform((data) => {
        const payload: Record<string, unknown> = { ...omitTieredPriceOverrides(data) };
        if (!props.options.canSelectDeals) delete payload.deal_id;
        return payload;
    });
    const settings = { preserveScroll: true, onSuccess: () => { open.value = false; form.reset(); } };
    if (props.quote) form.put(route('crm.sales.quotes.update', { quote: props.quote.id }), settings);
    else form.post(route('crm.sales.quotes.store'), settings);
}
</script>
<template><Modal v-model:open="open" size="lg" :title="t(quote ? 'crm.sales.quotes.edit' : 'crm.sales.quotes.add')" :persistent="form.processing"><form id="crm-quote-form" class="grid gap-4 sm:grid-cols-2" @submit.prevent="submit"><Input v-model="form.title" class="sm:col-span-2" :label="t('crm.fields.title')" :error="form.errors.title" required maxlength="200" autofocus /><Select v-if="options.canSelectDeals" v-model="form.deal_id" :options="optionList(options.deals)" :label="t('crm.fields.deal')" :error="form.errors.deal_id" /><Select v-model="form.kind" :options="kinds" :label="t('crm.fields.type')" :error="form.errors.kind" /><Select v-model="form.price_list_id" :options="optionList(options.priceLists)" :label="t('crm.sales.priceLists.title')" :error="form.errors.price_list_id" /><Select v-model="form.contact_id" :options="optionList(options.contacts)" :label="t('crm.fields.contact')" :error="form.errors.contact_id" /><Select v-model="form.company_id" :options="optionList(options.companies)" :label="t('crm.fields.company')" :error="form.errors.company_id" /><Input v-model="form.currency" :label="t('crm.fields.currency')" :error="form.errors.currency" maxlength="3" required /><Input v-model="form.probability_percent" type="number" min="0" max="100" :label="t('crm.sales.quotes.probability')" :error="form.errors.probability_percent" required /><Input v-model="form.valid_until" type="date" :label="t('crm.fields.validUntil')" :error="form.errors.valid_until" optional /><fieldset class="grid gap-3 sm:col-span-2"><legend class="text-sm font-semibold text-ink">{{ t('crm.sales.quotes.lines') }}</legend><div v-for="(row, index) in form.lines" :key="index" class="glass-well grid gap-3 rounded-control p-3 sm:grid-cols-2"><Select v-model="row.product_id" :options="optionList(options.products)" :label="t('crm.sales.catalogue.title')" @update:model-value="selectProduct(index)" /><Input v-model="row.name" :label="t('crm.fields.name')" :error="form.errors[`lines.${index}.name`]" required /><Input v-model="row.quantity_milli" type="number" min="1" :label="t('crm.sales.quotes.quantity')" :error="form.errors[`lines.${index}.quantity_milli`]" required /><Input v-model="row.unit_price_amount" type="number" min="0" :label="t('crm.fields.unitPrice')" :hint="form.price_list_id && row.product_id ? t('crm.sales.quotes.tieredPrice') : undefined" :error="form.errors[`lines.${index}.unit_price_amount`]" :disabled="Boolean(form.price_list_id && row.product_id)" :required="!form.price_list_id || !row.product_id" /><Input v-model="row.discount_amount" type="number" min="0" :label="t('crm.sales.quotes.discount')" :error="form.errors[`lines.${index}.discount_amount`]" /><Input v-model="row.tax_bps" type="number" min="0" max="10000" :label="t('crm.sales.quotes.tax')" :error="form.errors[`lines.${index}.tax_bps`]" /><Button icon size="sm" variant="ghost" :disabled="form.lines.length === 1" :aria-label="t('crm.sales.quotes.removeLine')" @click="form.lines.splice(index, 1)"><template #icon><Trash2 class="size-4" aria-hidden="true" /></template></Button></div><Button size="sm" variant="ghost" class="justify-self-start" @click="form.lines.push(line())"><template #icon><Plus class="size-4" aria-hidden="true" /></template>{{ t('crm.sales.quotes.addLine') }}</Button></fieldset><Textarea v-model="form.terms" :label="t('crm.sales.quotes.terms')" :error="form.errors.terms" optional /><Textarea v-model="form.notes" :label="t('crm.sales.quotes.notes')" :error="form.errors.notes" optional /></form><template #footer><Button variant="ghost" @click="open = false">{{ t('crm.common.cancel') }}</Button><Button form="crm-quote-form" type="submit" variant="primary" :loading="form.processing">{{ t('crm.common.save') }}</Button></template></Modal></template>
